sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (String(previous.getValue('underwriter')))
        return; // already had an underwriter - that is a reassignment, handled by "LOA trigger on underwriter reassignment"

    var triggerReasonId = new UWTriggerReasonResolver().resolve({
        consumer: 'loa',
        isFirstEver: true
    });
    if (!triggerReasonId) {
        gs.error('[LOA trigger on first underwriter assignment] no trigger_reason resolved for submission_line ' +
            current.getUniqueValue() + ' - loa_evaluation NOT created');
        return;
    }

    new LOAEvaluationVersionService().createNextVersion(current.getUniqueValue(), triggerReasonId);

})(current, previous);
